  // Media Methods
  async addMedia(url: string, metadata?: any): Promise<any> {
    const sourceUrl = String(url || "").trim()
    const {
      timeoutMs,
      media_type,
      urls: rawUrls,
      requestScope,
      signal,
      ...rest
    } = metadata || {}
    const urls = Array.isArray(rawUrls)
      ? rawUrls
          .map((item: unknown) => String(item || "").trim())
          .filter((item: string) => item.length > 0)
      : typeof rawUrls === "string" && rawUrls.trim()
        ? [rawUrls.trim()]
        : sourceUrl
          ? [sourceUrl]
          : []
    if (urls.length === 0) {
      throw new Error("addMedia requires a URL")
    }
    const resolvedMediaType =
      typeof media_type === "string" && media_type.trim()
        ? media_type.trim()
        : inferUploadMediaTypeFromUrl(urls[0])
    const scopeFields = requestScopeFields(
      requestScope as ServicePromptRequestScope | undefined
    )

    return await bgUpload<any>({
      path: "/api/v1/media/add",
      method: "POST",
      fields: {
        ...rest,
        media_type: resolvedMediaType,
        urls
      },
      timeoutMs,
      abortSignal: signal as AbortSignal | undefined,
      ...scopeFields
    })
  }

